-- Keys of 7, 2 426, 1 984, 21, 1 949 and 2 402 characters, in that order, under one index:
-- a leaf of them outgrows a page on the last, and the cut at its entry-count midpoint puts
-- more than a page in one half (the in-memory store refuses that page). The node is cut
-- where every piece fits, and every row is stored. `@no-txn`: inside the harness's
-- isolating block the rows would stay staged and never reach the tree.
-- @no-txn
-- @setup
DROP TABLE IF EXISTS nlk;
CREATE TABLE nlk (a text);
CREATE INDEX nlk_i ON nlk (a);
